App.Utils.CalendarDefaultView=(function(){const FILTER_TYPE_ALL='all';const FILTER_TYPE_PROVIDER='provider';const FILTER_TYPE_SERVICE='service';const EVENT_COLORS={unavailability:'#879DB4',blockedPeriod:'#d65069',notWorking:'#BEBEBE',default:'#7cbae8',};const $calendarPage=$('#calendar-page');const $reloadAppointments=$('#reload-appointments');const $calendar=$('#calendar');const $selectFilterItem=$('#select-filter-item');const $appointmentsModal=$('#appointments-modal');const $unavailabilitiesModal=$('#unavailabilities-modal');const $header=$('#header');const $footer=$('#footer');const $notification=$('#notification');const $calendarToolbar=$('#calendar-toolbar');const moment=window.moment;let $popoverTarget=null;let fullCalendar=null;let lastFocusedEventData=null;let calendarTimeRange=null;function getCalendarHeight(){const offset=$footer.outerHeight()+$header.outerHeight()+$calendarToolbar.outerHeight()+35;const height=window.innerHeight-offset;return Math.max(height,700);}
function getSelectedFilterType(){return $selectFilterItem.find('option:selected').attr('type');}
function isProviderFilter(){return getSelectedFilterType()===FILTER_TYPE_PROVIDER;}
function findProvider(providerId){return vars('available_providers').find((provider)=>Number(provider.id)===Number(providerId));}
function getWorkingTimeRange(){const range={start:Infinity,end:-Infinity};const selectedFilterId=$selectFilterItem.val();if(selectedFilterId===FILTER_TYPE_ALL){addWorkingPlanToRange(range,JSON.parse(vars('company_working_plan')));}else{const providers=isProviderFilter()?[findProvider(selectedFilterId)].filter(Boolean):vars('available_providers');providers.forEach((provider)=>{const workingPlan=JSON.parse(provider?.settings?.working_plan||vars('company_working_plan'),);addWorkingPlanToRange(range,workingPlan);addWorkingPlanExceptionsToRange(range,provider);});}
if(!Number.isFinite(range.start)||!Number.isFinite(range.end)){return{start:'00:00:00',end:'24:00:00'};}
return{start:formatCalendarTime(range.start),end:formatCalendarTime(range.end),};}
function addWorkingPlanToRange(range,workingPlan){Object.values(workingPlan).forEach((dayPlan)=>{if(!dayPlan?.start||!dayPlan?.end){return;}
range.start=Math.min(range.start,timeToMinutes(dayPlan.start));range.end=Math.max(range.end,timeToMinutes(dayPlan.end));});}
function addWorkingPlanExceptionsToRange(range,provider){const rawExceptions=JSON.parse(provider?.settings?.working_plan_exceptions||'[]');const exceptions=Array.isArray(rawExceptions)?rawExceptions:Object.entries(rawExceptions).map(([date,exception])=>({startDate:date,endDate:date,startTime:exception?.start,endTime:exception?.end,}));const viewStart=moment(fullCalendar.view.activeStart).startOf('day');const viewEnd=moment(fullCalendar.view.activeEnd).startOf('day');exceptions.forEach((exception)=>{const startDate=moment(exception.startDate);const endDate=moment(exception.endDate||exception.startDate);if(endDate.isBefore(viewStart,'day')||!startDate.isBefore(viewEnd,'day')){return;}
const startTime=exception.startTime||exception.start;const endTime=exception.endTime||exception.end;if(startTime&&endTime){range.start=Math.min(range.start,timeToMinutes(startTime));range.end=Math.max(range.end,timeToMinutes(endTime));}});}
function timeToMinutes(time){const[hours,minutes]=time.split(':').map(Number);return hours*60+minutes;}
function formatCalendarTime(minutes){const hours=String(Math.floor(minutes/60)).padStart(2,'0');const remainingMinutes=String(minutes%60).padStart(2,'0');return`${hours}:${remainingMinutes}:00`;}
function updateCalendarTimeRange(){if(!$selectFilterItem.val()){return;}
const timeRange=getWorkingTimeRange();if(calendarTimeRange?.start===timeRange.start&&calendarTimeRange?.end===timeRange.end){return;}
calendarTimeRange=timeRange;fullCalendar.setOption('slotMinTime',timeRange.start);fullCalendar.setOption('slotMaxTime',timeRange.end);}
function findService(serviceId){return vars('available_services').find((service)=>Number(service.id)===Number(serviceId));}
function closePopover(){if($popoverTarget){$popoverTarget.popover('dispose');$popoverTarget=null;}}
function isUnavailability(eventData){return Boolean(Number(eventData?.is_unavailability));}
function isWorkingPlanException(eventData){return eventData?.workingPlanException!==undefined;}
function populateAppointmentModal(appointment){const customer=appointment.customer;App.Components.AppointmentsModal.resetModal();$appointmentsModal.find('.modal-header h3').text(lang('edit_appointment_title'));$appointmentsModal.find('#appointment-id').val(appointment.id);$appointmentsModal.find('#select-service').val(appointment.id_services).trigger('change');$appointmentsModal.find('#select-provider').val(appointment.id_users_provider);App.Utils.UI.setDateTimePickerValue($appointmentsModal.find('#start-datetime'),moment(appointment.start_datetime).toDate(),);App.Utils.UI.setDateTimePickerValue($appointmentsModal.find('#end-datetime'),moment(appointment.end_datetime).toDate(),);$appointmentsModal.find('#customer-id').val(appointment.id_users_customer);$appointmentsModal.find('#first-name').val(customer.first_name);$appointmentsModal.find('#last-name').val(customer.last_name);$appointmentsModal.find('#email').val(customer.email);$appointmentsModal.find('#phone-number').val(customer.phone_number);$appointmentsModal.find('#address').val(customer.address);$appointmentsModal.find('#city').val(customer.city);$appointmentsModal.find('#zip-code').val(customer.zip_code);$appointmentsModal.find('#language').val(customer.language);$appointmentsModal.find('#timezone').val(customer.timezone);$appointmentsModal.find('#customer-notes').val(customer.notes);$appointmentsModal.find('#custom-field-1').val(customer.custom_field_1);$appointmentsModal.find('#custom-field-2').val(customer.custom_field_2);$appointmentsModal.find('#custom-field-3').val(customer.custom_field_3);$appointmentsModal.find('#custom-field-4').val(customer.custom_field_4);$appointmentsModal.find('#custom-field-5').val(customer.custom_field_5);$appointmentsModal.find('#appointment-location').val(appointment.location);$appointmentsModal.find('#appointment-meeting-link').val(appointment.meeting_link);$appointmentsModal.find('#appointment-status').val(appointment.status);$appointmentsModal.find('#appointment-notes').val(appointment.notes);App.Components.ColorSelection.setColor($appointmentsModal.find('#appointment-color'),appointment.color);$appointmentsModal.modal('show');}
function populateUnavailabilityModal(unavailability){App.Components.UnavailabilitiesModal.resetModal();$unavailabilitiesModal.find('.modal-header h3').text(lang('edit_unavailability_title'));App.Utils.UI.setDateTimePickerValue($unavailabilitiesModal.find('#unavailability-start'),moment(unavailability.start_datetime).toDate(),);App.Utils.UI.setDateTimePickerValue($unavailabilitiesModal.find('#unavailability-end'),moment(unavailability.end_datetime).toDate(),);$unavailabilitiesModal.find('#unavailability-id').val(unavailability.id);$unavailabilitiesModal.find('#unavailability-provider').val(unavailability.id_users_provider);$unavailabilitiesModal.find('#unavailability-notes').val(unavailability.notes);$unavailabilitiesModal.modal('show');}
function updateProviderWorkingPlanExceptions(providerId,workingPlanExceptions){for(const provider of vars('available_providers')){if(Number(provider.id)===Number(providerId)){provider.settings.working_plan_exceptions=JSON.stringify(workingPlanExceptions);break;}}}
function handleEditWorkingPlanException(data){const{workingPlanException,provider}=data;App.Components.WorkingPlanExceptionsModal.edit(workingPlanException).done((updatedException)=>{const successCallback=(response)=>{App.Layouts.Backend.displayNotification(lang('working_plan_exception_saved'));let exceptions=JSON.parse(provider.settings.working_plan_exceptions||'[]');if(!Array.isArray(exceptions)){exceptions=[];}
const existingIndex=exceptions.findIndex((e)=>e.id===updatedException.id);if(existingIndex>=0){exceptions[existingIndex]=updatedException;}else{if(response&&response.id){updatedException.id=response.id;}
exceptions.push(updatedException);}
provider.settings.working_plan_exceptions=JSON.stringify(exceptions);$reloadAppointments.trigger('click');};App.Http.Calendar.saveWorkingPlanException(updatedException,provider.id,successCallback,null);});}
function handleDeleteWorkingPlanException(){const providerId=$selectFilterItem.val();const provider=findProvider(providerId);if(!provider){throw new Error('Provider could not be found: '+providerId);}
const data=lastFocusedEventData.extendedProps.data;const exception=data.workingPlanException;if(!exception||!exception.id){App.Layouts.Backend.displayNotification(lang('working_plan_exception_deleted'));$reloadAppointments.trigger('click');return;}
const successCallback=()=>{App.Layouts.Backend.displayNotification(lang('working_plan_exception_deleted'));let exceptions=JSON.parse(provider.settings.working_plan_exceptions||'[]');if(Array.isArray(exceptions)){exceptions=exceptions.filter((e)=>e.id!==exception.id);provider.settings.working_plan_exceptions=JSON.stringify(exceptions);}
$reloadAppointments.trigger('click');};App.Http.Calendar.deleteWorkingPlanException(exception.id,providerId,successCallback);}
function onEditPopoverClick(){closePopover();const data=lastFocusedEventData.extendedProps.data;if(isWorkingPlanException(data)){handleEditWorkingPlanException(data);}else if(!isUnavailability(data)){populateAppointmentModal(data);}else{const unavailability={...data,start_datetime:moment(lastFocusedEventData.start).format('YYYY-MM-DD HH:mm:ss'),end_datetime:moment(lastFocusedEventData.end).format('YYYY-MM-DD HH:mm:ss'),};populateUnavailabilityModal(unavailability);}}
function onDeletePopoverClick(){closePopover();const data=lastFocusedEventData.extendedProps.data;if(isWorkingPlanException(data)){handleDeleteWorkingPlanException();}else if(!isUnavailability(data)){handleDeleteAppointment(data.id);}else{App.Http.Calendar.deleteUnavailability(data.id).done(()=>{$reloadAppointments.trigger('click');});}}
function handleDeleteAppointment(appointmentId){App.Utils.Message.show(lang('delete_appointment_title'),lang('notify_users_on_delete_question'),[{text:lang('cancel'),click:(event,notifyModal)=>notifyModal.hide(),},{text:lang('no'),click:(event,notifyModal)=>{notifyModal.hide();App.Http.Calendar.deleteAppointment(appointmentId,null,false).done(()=>{$reloadAppointments.trigger('click');});},},{text:lang('yes'),click:(event,notifyModal)=>{notifyModal.hide();const reasonButtons=[{text:lang('cancel'),click:(event,messageModal)=>messageModal.hide(),},{text:lang('delete'),click:(event,messageModal)=>{const reason=$('#cancellation-reason').val();messageModal.hide();App.Http.Calendar.deleteAppointment(appointmentId,reason,true).done(()=>{$reloadAppointments.trigger('click');});},},];App.Utils.Message.show(lang('delete_appointment_title'),lang('write_appointment_removal_reason'),reasonButtons,);$('<textarea/>',{class:'form-control w-100',id:'cancellation-reason',rows:'3',}).appendTo('#message-modal .modal-body');},},]);}
function onEventClick(info){const $target=$(info.el);closePopover();let $html;let displayEdit;let displayDelete;if($target.hasClass('fc-blocked-period')){$html=App.Utils.CalendarEventPopover.buildBlockedPeriodPopover(info);}else if($target.hasClass('fc-working-plan-exception')){displayEdit=$target.hasClass('fc-custom')&&vars('privileges').appointments.edit?'':'d-none';displayDelete=$target.hasClass('fc-custom')&&vars('privileges').appointments.delete?'me-2':'d-none';$html=App.Utils.CalendarEventPopover.buildWorkingPlanExceptionPopover(info,displayEdit,displayDelete);}else if($target.hasClass('fc-unavailability')){const isCustom=$target.hasClass('fc-custom');displayEdit=isCustom&&vars('privileges').appointments.edit?'':'d-none';displayDelete=isCustom&&vars('privileges').appointments.delete?'me-2':'d-none';$html=App.Utils.CalendarEventPopover.buildUnavailabilityPopover(info,displayEdit,displayDelete);}else{displayEdit=vars('privileges').appointments.edit?'':'d-none';displayDelete=vars('privileges').appointments.delete?'me-2':'d-none';$html=App.Utils.CalendarEventPopover.buildAppointmentPopover(info,displayEdit,displayDelete);}
$target.popover({placement:'top',title:App.Utils.String.escapeHtml(info.event.title),content:$html,html:true,container:'#calendar',trigger:'manual',});lastFocusedEventData=info.event;$target.popover('show');$popoverTarget=$target;const $popover=$calendarPage.find('.popover');if($popover.length&&$popover.position().top<200){$popover.css('top','200px');}}
function onEventResize(info){if(!vars('privileges').appointments.edit){info.revert();App.Layouts.Backend.displayNotification(lang('no_privileges_edit_appointments'));return;}
if($notification.is(':visible')){$notification.hide('bind');}
const eventData=info.event.extendedProps.data;if(!isUnavailability(eventData)){handleAppointmentResize(info,eventData);}else{handleUnavailabilityResize(info,eventData);}}
function handleAppointmentResize(info,eventData){eventData.end_datetime=moment(eventData.end_datetime).add({days:info.endDelta.days,milliseconds:info.endDelta.milliseconds}).format('YYYY-MM-DD HH:mm:ss');const appointment=prepareAppointmentForSave(eventData);const successCallback=(notifyUsers)=>{const undoFunction=()=>{appointment.end_datetime=eventData.end_datetime=moment(appointment.end_datetime).add({days:-info.endDelta.days,milliseconds:-info.endDelta.milliseconds}).format('YYYY-MM-DD HH:mm:ss');App.Http.Calendar.saveAppointment(appointment,null,null,null,notifyUsers).done(()=>$notification.hide('blind'),);info.revert();};App.Layouts.Backend.displayNotification(lang('appointment_updated'),[{label:lang('undo'),function:undoFunction},]);info.event.setProp('data',eventData);};showNotifyUsersDialog(appointment,successCallback,()=>info.revert());}
function handleUnavailabilityResize(info,eventData){const unavailability={id:eventData.id,start_datetime:moment(info.event.start).format('YYYY-MM-DD HH:mm:ss'),end_datetime:moment(info.event.end).format('YYYY-MM-DD HH:mm:ss'),id_users_provider:eventData.id_users_provider,};eventData.end_datetime=unavailability.end_datetime;const successCallback=()=>{const undoFunction=()=>{unavailability.end_datetime=eventData.end_datetime=moment(unavailability.end_datetime).add({days:-info.endDelta.days,milliseconds:-info.endDelta.milliseconds}).format('YYYY-MM-DD HH:mm:ss');App.Http.Calendar.saveUnavailability(unavailability,null,null,true).done(()=>$notification.hide('blind'),);info.revert();};App.Layouts.Backend.displayNotification(lang('unavailability_updated'),[{label:lang('undo'),function:undoFunction},]);info.event.setProp('data',eventData);};App.Http.Calendar.saveUnavailability(unavailability,successCallback,null,false,()=>info.revert());}
function onEventDrop(info){if(!vars('privileges').appointments.edit){info.revert();App.Layouts.Backend.displayNotification(lang('no_privileges_edit_appointments'));return;}
if($notification.is(':visible')){$notification.hide('bind');}
const eventData=info.event.extendedProps.data;if(!isUnavailability(eventData)){handleAppointmentDrop(info,eventData);}else{handleUnavailabilityDrop(info,eventData);}}
function handleAppointmentDrop(info,eventData){const appointment=prepareAppointmentForSave(eventData);appointment.start_datetime=moment(appointment.start_datetime).add({days:info.delta.days,milliseconds:info.delta.milliseconds}).format('YYYY-MM-DD HH:mm:ss');appointment.end_datetime=moment(appointment.end_datetime).add({days:info.delta.days,milliseconds:info.delta.milliseconds}).format('YYYY-MM-DD HH:mm:ss');appointment.is_unavailability=0;eventData.start_datetime=appointment.start_datetime;eventData.end_datetime=appointment.end_datetime;const successCallback=(notifyUsers)=>{const undoFunction=()=>{const delta={days:-info.delta.days,milliseconds:-info.delta.milliseconds};appointment.start_datetime=moment(appointment.start_datetime).add(delta).format('YYYY-MM-DD HH:mm:ss');appointment.end_datetime=moment(appointment.end_datetime).add(delta).format('YYYY-MM-DD HH:mm:ss');eventData.start_datetime=appointment.start_datetime;eventData.end_datetime=appointment.end_datetime;App.Http.Calendar.saveAppointment(appointment,null,null,null,notifyUsers).done(()=>$notification.hide('blind'),);info.revert();};App.Layouts.Backend.displayNotification(lang('appointment_updated'),[{label:lang('undo'),function:undoFunction},]);};showNotifyUsersDialog(appointment,successCallback,()=>info.revert());}
function handleUnavailabilityDrop(info,eventData){const unavailability={id:eventData.id,start_datetime:moment(info.event.start).format('YYYY-MM-DD HH:mm:ss'),end_datetime:moment(info.event.end).format('YYYY-MM-DD HH:mm:ss'),id_users_provider:eventData.id_users_provider,};const successCallback=()=>{const undoFunction=()=>{const delta={days:-info.delta.days,milliseconds:-info.delta.milliseconds};unavailability.start_datetime=moment(unavailability.start_datetime).add(delta).format('YYYY-MM-DD HH:mm:ss');unavailability.end_datetime=moment(unavailability.end_datetime).add(delta).format('YYYY-MM-DD HH:mm:ss');unavailability.is_unavailability=1;eventData.start_datetime=unavailability.start_datetime;eventData.end_datetime=unavailability.end_datetime;App.Http.Calendar.saveUnavailability(unavailability,null,null,true).done(()=>$notification.hide('blind'),);info.revert();};App.Layouts.Backend.displayNotification(lang('unavailability_updated'),[{label:lang('undo'),function:undoFunction},]);};App.Http.Calendar.saveUnavailability(unavailability,successCallback,null,false,()=>info.revert());}
function prepareAppointmentForSave(eventData){const appointment={...eventData};appointment.is_unavailability=Number(appointment.is_unavailability);delete appointment.customer;delete appointment.provider;delete appointment.service;return appointment;}
function showNotifyUsersDialog(appointment,successCallback,revertCallback){App.Utils.Message.show(lang('appointment_update'),lang('notify_users_on_update_question'),[{text:lang('no'),click:(event,messageModal)=>{messageModal.hide();App.Http.Calendar.saveAppointmentWithConflictHandling(appointment,null,()=>successCallback(false),null,false,revertCallback,);},},{text:lang('yes'),click:(event,messageModal)=>{messageModal.hide();App.Http.Calendar.saveAppointmentWithConflictHandling(appointment,null,()=>successCallback(true),null,true,revertCallback,);},},]);}
function onDateClick(info){if(info.allDay){fullCalendar.changeView('timeGridDay');fullCalendar.gotoDate(info.date);}}
function onSelect(info){if(info.allDay)return;const buttons=[{text:lang('unavailability'),click:(event,messageModal)=>{$('#insert-unavailability').trigger('click');const $providerSelect=$('#unavailability-provider');if(isProviderFilter()){$providerSelect.val($selectFilterItem.val());}else{$providerSelect.find('option:first').prop('selected',true);}
$providerSelect.trigger('change');App.Utils.UI.setDateTimePickerValue($('#unavailability-start'),info.start);App.Utils.UI.setDateTimePickerValue($('#unavailability-end'),info.end);messageModal.hide();},},{text:lang('appointment'),click:(event,messageModal)=>{$('#insert-appointment').trigger('click');preselectServiceAndProvider();App.Utils.UI.setDateTimePickerValue($('#start-datetime'),info.start);App.Utils.UI.setDateTimePickerValue($('#end-datetime'),App.Pages.Calendar.getSelectionEndDate(info),);messageModal.hide();},},];App.Utils.Message.show(lang('add_new_event'),lang('what_kind_of_event'),buttons);$('#message-modal .modal-footer').addClass('justify-content-between').find('.btn').css('width','calc(50% - 10px)');fullCalendar.unselect();return false;}
function preselectServiceAndProvider(){const $serviceSelect=$appointmentsModal.find('#select-service');const $providerSelect=$appointmentsModal.find('#select-provider');if(isProviderFilter()){const provider=findProvider($selectFilterItem.val());if(provider){const service=vars('available_services').find((s)=>provider.services.indexOf(s.id)!==-1);if(service){$serviceSelect.val(service.id);}}
if(!$serviceSelect.val()){$serviceSelect.find('option:first').prop('selected',true);}
$serviceSelect.trigger('change');if(provider){$providerSelect.val(provider.id);}
if(!$providerSelect.val()){$providerSelect.find('option:first').prop('selected',true);}
$providerSelect.trigger('change');}else{const service=findService($selectFilterItem.val());if(service){$serviceSelect.val(service.id).trigger('change');}}}
function onWindowResize(){fullCalendar.setOption('height',getCalendarHeight());}
function onDatesSet(){if(!$selectFilterItem.val())return;updateCalendarTimeRange();refreshCalendarAppointments($calendar,$selectFilterItem.val(),getSelectedFilterType(),fullCalendar.view.activeStart,fullCalendar.view.activeEnd,);$(window).trigger('resize');$('.close-popover').each(()=>closePopover());$('.fv-events').each((index,el)=>$(el).popover());}
function refreshCalendarAppointments($calendar,recordId,filterType,startDate,endDate){$('#loading').css('visibility','hidden');const formattedStartDate=moment(startDate).format('YYYY-MM-DD');const formattedEndDate=moment(endDate).format('YYYY-MM-DD');App.Http.Calendar.getCalendarAppointments(recordId,formattedStartDate,formattedEndDate,filterType).done((response)=>{fullCalendar.getEventSources().forEach((source)=>source.remove());const events=[];events.push(...createAppointmentEvents(response.appointments));events.push(...createUnavailabilityEvents(response.unavailabilities));events.push(...createBlockedPeriodEvents(response.blocked_periods));if(fullCalendar.view.type!=='dayGridMonth'){events.push(...createWorkingPlanEvents(recordId));}
fullCalendar.addEventSource(events);}).always(()=>{$('#loading').css('visibility','');});}
function createAppointmentEvents(appointments){return appointments.map((appointment)=>{const customerName=[appointment.customer.first_name,appointment.customer.last_name].filter(Boolean).join(' ');const type=getSelectedFilterType()!==FILTER_TYPE_SERVICE?appointment.service.name:[appointment.provider.first_name,appointment.provider.last_name].filter(Boolean).join(' ');const title=customerName?customerName+' - '+type:appointment.service.name;return{id:appointment.id,title,start:moment(appointment.start_datetime).toDate(),end:moment(appointment.end_datetime).toDate(),allDay:false,color:appointment.color,data:appointment,display:'block',};});}
function createUnavailabilityEvents(unavailabilities){return unavailabilities.map((unavailability)=>{let notes=unavailability.notes?' - '+unavailability.notes:'';if(notes.length>33){notes=' - '+unavailability.notes.substring(0,30)+'...';}
return{title:lang('unavailability')+notes,start:moment(unavailability.start_datetime).toDate(),end:moment(unavailability.end_datetime).toDate(),allDay:false,color:EVENT_COLORS.unavailability,editable:true,className:'fc-unavailability fc-custom',data:unavailability,display:'block',};});}
function createBlockedPeriodEvents(blockedPeriods){if(!blockedPeriods)return[];return blockedPeriods.map((blockedPeriod)=>({title:blockedPeriod.name,start:moment(blockedPeriod.start_datetime).toDate(),end:moment(blockedPeriod.end_datetime).toDate(),allDay:true,backgroundColor:EVENT_COLORS.blockedPeriod,borderColor:EVENT_COLORS.blockedPeriod,textColor:'#ffffff',editable:false,className:'fc-blocked-period fc-unavailability',data:blockedPeriod,display:'block',}));}
function createWorkingPlanEvents(recordId){const events=[];const provider=findProvider(recordId);const workingPlan=JSON.parse(provider?.settings?.working_plan||vars('company_working_plan'));const rawExceptions=JSON.parse(provider?.settings?.working_plan_exceptions||'[]');const workingPlanExceptions={};const exceptionsMap={};if(Array.isArray(rawExceptions)){rawExceptions.forEach((exception)=>{const startDate=moment(exception.startDate);const endDate=moment(exception.endDate);while(startDate.isSameOrBefore(endDate)){const dateStr=startDate.format('YYYY-MM-DD');workingPlanExceptions[dateStr]={start:exception.startTime,end:exception.endTime,breaks:exception.breaks||[],};exceptionsMap[dateStr]=exception;startDate.add(1,'day');}});}else{Object.assign(workingPlanExceptions,rawExceptions);}
const firstWeekdayNumber=App.Utils.Date.getWeekdayId(vars('first_weekday'));const sortedWorkingPlan=App.Utils.Date.sortWeekDictionary(workingPlan,firstWeekdayNumber);const calendarDate=moment(fullCalendar.view.currentStart).clone();const viewEnd=fullCalendar.view.currentEnd;while(calendarDate.toDate()<viewEnd){const weekdayNumber=parseInt(calendarDate.format('d'));const weekdayName=App.Utils.Date.getWeekdayName(weekdayNumber);const weekdayDate=calendarDate.format('YYYY-MM-DD');if(workingPlanExceptions.hasOwnProperty(weekdayDate)){const exceptionData=workingPlanExceptions[weekdayDate];sortedWorkingPlan[weekdayName]=exceptionData&&exceptionData.start?exceptionData:null;const originalException=exceptionsMap[weekdayDate]||{startDate:weekdayDate,endDate:weekdayDate,startTime:exceptionData?.start||null,endTime:exceptionData?.end||null,breaks:exceptionData?.breaks||[],};events.push(createWorkingPlanExceptionEvent(weekdayDate,exceptionData,provider,originalException));}
if(!sortedWorkingPlan[weekdayName]){calendarDate.add(1,'day');continue;}
const dayPlan=sortedWorkingPlan[weekdayName];events.push(...createBreakEvents(calendarDate,dayPlan.breaks));calendarDate.add(1,'day');}
return events;}
function createWorkingPlanExceptionEvent(date,exception,provider,originalException){const startTime=exception?.start||'00:00';const endTime=exception?.end||'00:00';return{title:lang('working_plan_exception'),start:moment(date+' '+startTime,'YYYY-MM-DD HH:mm').toDate(),end:moment(date+' '+endTime,'YYYY-MM-DD HH:mm').add(1,'day').toDate(),allDay:true,color:EVENT_COLORS.unavailability,editable:false,className:'fc-working-plan-exception fc-custom',display:'block',extendedProps:{data:{workingPlanException:originalException,provider},},};}
function createBreakEvents(calendarDate,breaks){if(!breaks)return[];const dateStr=calendarDate.format('YYYY-MM-DD');return breaks.map((breakPeriod)=>({title:lang('break'),start:moment(dateStr+' '+breakPeriod.start).toDate(),end:moment(dateStr+' '+breakPeriod.end).toDate(),allDay:false,color:EVENT_COLORS.notWorking,editable:false,display:'background',className:'fc-unavailability fc-break',}));}
function addEventListeners(){$reloadAppointments.on('click',()=>{closePopover();updateCalendarTimeRange();refreshCalendarAppointments($calendar,$selectFilterItem.val(),getSelectedFilterType(),fullCalendar.view.activeStart,fullCalendar.view.activeEnd,);});$calendarPage.on('click','.close-popover',closePopover);$calendarPage.on('click','.edit-popover',onEditPopoverClick);$calendarPage.on('click','.delete-popover',onDeletePopoverClick);$selectFilterItem.on('change',()=>{const providerId=$selectFilterItem.val();const provider=findProvider(providerId);if(provider?.timezone){$('.provider-timezone').text(vars('timezones')[provider.timezone]);}
$('#insert-working-plan-exception').toggle(isProviderFilter());$reloadAppointments.trigger('click');window.localStorage.setItem('EasyAppointments.SelectFilterItem',providerId);});}
function getFormatSettings(){let columnFormat,timeFormat,slotTimeFormat;switch(vars('date_format')){case'DMY':columnFormat='ddd D/M';break;case'MDY':case'YMD':columnFormat='ddd M/D';break;default:throw new Error('Invalid date format setting: '+vars('date_format'));}
switch(vars('time_format')){case'military':timeFormat='HH:mm';slotTimeFormat='HH:mm';break;case'regular':timeFormat='h:mm a';slotTimeFormat='h a';break;default:throw new Error('Invalid time format setting: '+vars('time_format'));}
return{columnFormat,timeFormat,slotTimeFormat};}
function populateFilterDropdown(){$selectFilterItem.append(new Option(lang('all'),FILTER_TYPE_ALL,true,true));if(vars('available_providers').length>0){$('<optgroup/>',{label:lang('providers'),type:'providers-group',html:vars('available_providers').map((provider)=>$('<option/>',{value:provider.id,type:FILTER_TYPE_PROVIDER,'google-sync':provider.settings.google_sync,'caldav-sync':provider.settings.caldav_sync,text:provider.first_name+' '+provider.last_name,}),),}).appendTo($selectFilterItem);}
if(vars('available_services').length>0){$('<optgroup/>',{label:lang('services'),type:'services-group',html:vars('available_services').map((service)=>$('<option/>',{value:service.id,type:FILTER_TYPE_SERVICE,text:service.name,}),),}).appendTo($selectFilterItem);}}
function initialize(){const{columnFormat,timeFormat,slotTimeFormat}=getFormatSettings();const initialView=window.innerWidth<468?'timeGridDay':'timeGridWeek';const firstWeekdayNumber=App.Utils.Date.getWeekdayId(vars('first_weekday'));fullCalendar=new FullCalendar.Calendar($calendar[0],{initialView,locale:vars('language_code'),nowIndicator:true,height:getCalendarHeight(),editable:true,firstDay:firstWeekdayNumber,slotDuration:'00:15:00',snapDuration:'00:15:00',scrollTime:'07:00:00',slotLabelInterval:'01:00',eventTimeFormat:timeFormat,eventTextColor:'#333',eventColor:EVENT_COLORS.default,slotLabelFormat:slotTimeFormat,allDayContent:lang('all_day'),selectable:true,selectMirror:true,themeSystem:'bootstrap5',selectLongPressDelay:100,headerToolbar:{left:'prev,next today',center:'title',right:'timeGridDay,timeGridWeek,dayGridMonth',},buttonText:{today:lang('today'),day:lang('day'),week:lang('week'),month:lang('month'),},windowResize:onWindowResize,datesSet:onDatesSet,dateClick:onDateClick,eventClick:onEventClick,eventResize:onEventResize,eventDrop:onEventDrop,select:onSelect,});fullCalendar.render();$calendar.data('fullCalendar',fullCalendar);onWindowResize();populateFilterDropdown();$('#insert-working-plan-exception').hide();if(vars('role_slug')===App.Layouts.Backend.DB_SLUG_PROVIDER){$selectFilterItem.find('optgroup:eq(0) option[value="'+vars('user_id')+'"]').prop('selected',true);}
addEventListeners();const savedFilter=window.localStorage.getItem('EasyAppointments.SelectFilterItem');if(savedFilter&&$selectFilterItem.find('option[value="'+savedFilter+'"]').length){$selectFilterItem.val(savedFilter).trigger('change');}else{$reloadAppointments.trigger('click');}
if(vars('edit_appointment')){populateAppointmentModal(vars('edit_appointment'));fullCalendar.gotoDate(moment(vars('edit_appointment').start_datetime).toDate());}
if(!$selectFilterItem.find('option').length){$('#calendar-actions button').prop('disabled',true);}
setInterval(()=>{if($('.popover').length||App.Utils.CalendarSync.isCurrentlySyncing()){return;}
refreshCalendarAppointments($calendar,$selectFilterItem.val(),getSelectedFilterType(),fullCalendar.view.activeStart,fullCalendar.view.activeEnd,);},60000);}
return{initialize,FILTER_TYPE_ALL,FILTER_TYPE_PROVIDER,FILTER_TYPE_SERVICE,};})();
